// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 ) public {
        amount = bound(amount, 0, 1 ether);

        AttackerLike attacker = new AttackerLike();

        vm.deal(address(c), 1 ether);

        vm.prank(address(this));
        bool ok;
        try c.sendMoney(address(attacker), amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        if (amount > 0) {
            assertTrue(attacker.counter() == 1);
        } else {
            assertTrue(ok == true);
        }
    }
}

contract AttackerLike {
    uint public counter;

    receive() external payable {
        for (uint i = 0; i < 10; i++) {
            counter += 1;
        }
        counter = 1;
    }
}
